'use strict';

// MODULES //

import getDType from '@stdlib/ndarray-base-dtype';
import getData from '@stdlib/ndarray-base-data-buffer';
import getShape from '@stdlib/ndarray-base-shape';
import getStrides from '@stdlib/ndarray-base-strides';
import getOffset from '@stdlib/ndarray-base-offset';
import getOrder from '@stdlib/ndarray-base-order';


// MAIN //

/**
* Converts an ndarray-like object to an ndarray descriptor.
*
* @param {ndarrayLike} x - input ndarray
* @returns {Object} ndarray descriptor
*
* @example
* import zeros from '@stdlib/ndarray-zeros';
*
* var out = ndarraylike2descriptor( zeros( [ 2, 2 ] ) );
* // returns {...}
*/
function ndarraylike2descriptor( x ) {
	return {
		'dtype': getDType( x ),
		'data': getData( x ),
		'shape': getShape( x, true ),
		'strides': getStrides( x, true ),
		'offset': getOffset( x ),
		'order': getOrder( x )
	};
}


// EXPORTS //

export default ndarraylike2descriptor;
